# Stage 0 only: reconstruct published OLD models from manuscript, not recovered original code.
# No new models, parameter tuning, downloads or writes outside revision_stage0.
options(stringsAsFactors=FALSE)
root <- '.'
out <- file.path(root,'revision_stage0')
packages <- c('limma','edgeR','statmod','variancePartition','lme4','lmerTest','pbkrtest')
env <- do.call(rbind,lapply(packages,function(p){ok<-requireNamespace(p,quietly=TRUE);data.frame(package=p,loadable=ok,version=if(ok)as.character(packageVersion(p))else NA,path=if(ok)find.package(p)else NA)}))
write.csv(env,file.path(out,'stage0_R_runtime_packages.csv'),row.names=FALSE)
capture.output(sessionInfo(),file=file.path(out,'stage0_R_sessionInfo.txt'))
stopifnot(requireNamespace('limma',quietly=TRUE),requireNamespace('statmod',quietly=TRUE))
cw <- read.csv(file.path(root,'\u6295\u7a3f\u6750\u6599 - BMJ','Supplementary Data 3 provenance crosswalk.csv'),check.names=FALSE,fileEncoding="UTF-8-BOM")
pairs<-read.csv(file.path(out,'stage0_primary_pairs.csv'),check.names=FALSE,fileEncoding="UTF-8-BOM")
subj<-factor(pairs$subject);label<-as.integer(sub('D','',pairs$collection_label));xcat<-model.matrix(~factor(label,levels=1:7));xlin<-model.matrix(~I(label-4))
allstats<-list();comparisons<-list();correlations<-list()
for(layer in c('miRNA','GENCODE')){
 p<-list.files(file.path(out,'source_extract/TRACKB_SOURCE_DATA_PACKAGE/01_GEO_processed_expression'),pattern=if(layer=='miRNA')'_miRNA_' else '_gencode_',full.names=TRUE)
 con<-gzfile(p,'rt');lines<-readLines(con);close(con)
 ids<-readLines(file.path(out,paste0('stage0_',layer,'_retained_features.txt')))
 keep<-c(TRUE,sub('\t.*$','',lines[-1])%in%ids)
 dat<-read.delim(text=paste(lines[keep],collapse='\n'),header=TRUE,row.names=1,check.names=FALSE,fileEncoding="UTF-8-BOM")
 rm(lines);invisible(gc())
 csf<-vapply(seq_len(nrow(pairs)),function(i)cw$expression_column_identifier[cw$subject_identifier==pairs$subject[i]&cw$collection_label==pairs$collection_label[i]&cw$biofluid=='CSF'&cw$analysis_disposition=='PRIMARY_INCLUDED'],character(1))
 plasma<-vapply(seq_len(nrow(pairs)),function(i)cw$expression_column_identifier[cw$subject_identifier==pairs$subject[i]&cw$collection_label==pairs$collection_label[i]&cw$biofluid=='plasma'&cw$analysis_disposition=='PRIMARY_INCLUDED'],character(1))
 g<-log2(as.matrix(dat[,csf])+1)-log2(as.matrix(dat[,plasma])+1)
 fitOld<-function(y,design){rho<-limma::duplicateCorrelation(y,design,block=subj)$consensus.correlation;fit<-limma::lmFit(y,design,block=subj,correlation=rho);list(fit=fit,rho=rho)}
 fc<-fitOld(g,xcat);fl<-fitOld(g,xlin)
 av<-limma::eBayes(limma::contrasts.fit(fc$fit,matrix(c(1,rep(1/7,6)),ncol=1)),trend=TRUE,robust=TRUE)
 li<-limma::eBayes(fl$fit,trend=TRUE,robust=TRUE)
 ca<-limma::eBayes(fc$fit,trend=TRUE,robust=TRUE)
 ct<-limma::topTable(ca,coef=2:7,number=Inf,sort.by='none')
 reference<-setdiff(rownames(g),if(layer=='miRNA')'hsa-miR-486-5p' else 'RNY4:misc_RNA')
 gr<-sweep(g,2,colMeans(g[reference,,drop=FALSE]),'-')
 fr<-fitOld(gr,xlin);co<-limma::eBayes(fr$fit,trend=TRUE,robust=TRUE)
 res<-data.frame(feature=rownames(g),mean_gradient=av$coefficients[,1],mean_gradient_P=av$p.value[,1],mean_gradient_FDR=p.adjust(av$p.value[,1],'BH'),linear_slope=li$coefficients[,2],linear_P=li$p.value[,2],linear_FDR=p.adjust(li$p.value[,2],'BH'),categorical_P=ct$P.Value,categorical_FDR=p.adjust(ct$P.Value,'BH'),composition_linear_effect=co$coefficients[,2],composition_linear_P=co$p.value[,2],composition_linear_BH_FDR=p.adjust(co$p.value[,2],'BH'))
 old<-read.csv(file.path(root,'\u6295\u7a3f\u6750\u6599 - BMJ',if(layer=='miRNA')'Supplementary Data 1 miRNA results.csv' else 'Supplementary Data 2 GENCODE results.csv'))
 old<-old[match(res$feature,old$feature),]
 comparisons[[layer]]<-do.call(rbind,lapply(setdiff(names(res),'feature'),function(k)data.frame(layer=layer,metric=k,max_abs_difference=max(abs(res[[k]]-old[[k]])),status=if(max(abs(res[[k]]-old[[k]]))<1e-6)'PASS' else 'MODIFY',evidence='Reconstructed manuscript model; original scripts unavailable; current package versions in sessionInfo')))
 counts<-c(mean=sum(res$mean_gradient_FDR<.05),linear=sum(res$linear_FDR<.05),categorical=sum(res$categorical_FDR<.05),composition=sum(res$linear_FDR<.05&res$composition_linear_BH_FDR<.05&res$linear_slope*res$composition_linear_effect>0))
 print(list(layer=layer,counts=counts,max_differences=comparisons[[layer]]))
 correlations[[layer]]<-data.frame(layer=layer,model=c('categorical','linear','composition_linear'),duplicateCorrelation=c(fc$rho,fl$rho,fr$rho))
 write.csv(res,file.path(out,paste0('stage0_legacy_refit_',layer,'.csv')),row.names=FALSE)
}
write.csv(do.call(rbind,comparisons),file.path(out,'stage0_legacy_refit_comparison.csv'),row.names=FALSE)
write.csv(do.call(rbind,correlations),file.path(out,'stage0_legacy_refit_correlations.csv'),row.names=FALSE)
